import json,numpy as np
cams=json.load(open('/app/runs/hammer/shaft4_after_close/meta.json'))['cameras']
def ray(name,uv):
 c=cams[name]; K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];t=E[:,3];o=-R.T@t;d=R.T@np.linalg.inv(K)@np.array([*uv,1]);return o,d/np.linalg.norm(d)
for ego in [(520,155),(520,160),(525,165),(515,155)]:
 for sh in [(710,410),(720,410),(700,400),(700,420),(730,400)]:
  o1,d1=ray('egocentric_mirrored_camera',ego);o2,d2=ray('over_shoulder_left_camera',sh)
  A=np.array([d1,-d2]).T; b=o2-o1; s=np.linalg.lstsq(A,b,rcond=None)[0];p1=o1+s[0]*d1;p2=o2+s[1]*d2;p=(p1+p2)/2
  if .0<p[0]<1.2 and -.5<p[1]<.7: print(ego,sh,np.round(p,3),'miss',round(np.linalg.norm(p1-p2),3))
PY

