import json,numpy as np
cams=json.load(open('/app/runs/hammer/head2_push_obs/meta.json'))['cameras']
def ray(n,uv):
 c=cams[n];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];o=-R.T@E[:,3];d=R.T@np.linalg.inv(K)@np.array([*uv,1]);return o,d/np.linalg.norm(d)
def tri(a,b):
 o1,d1=ray('egocentric_mirrored_camera',a);o2,d2=ray('over_shoulder_left_camera',b);A=np.array([d1,-d2]).T;s=np.linalg.lstsq(A,o2-o1,rcond=None)[0];p1=o1+s[0]*d1;p2=o2+s[1]*d2;return (p1+p2)/2,np.linalg.norm(p1-p2)
for a in [(680,330),(690,350),(700,365),(710,340),(690,375)]:
